uart_puertos = {}
def uart_configurar(puerto, rx, tx, baudios, bloque):
    try:
        uart = UART(puerto, baudrate=int(baudios), rx=rx, tx=tx, timeout=0)
    except (ValueError, OSError) as error:
        rb_fail(bloque, "No se pudo iniciar UART %s: %s" % (puerto, error))
    uart_puertos[puerto] = [uart, b"", "", False]  # UART, búfer, última línea, línea nueva

uart_puertos = {}
def uart_puerto(puerto, bloque):
    datos = uart_puertos.get(puerto)
    if datos is None:
        rb_fail(bloque, "Configura UART %s al iniciar" % puerto)
    # Lee sin bloquear y guarda la última línea completa recibida.
    while datos[0].any():
        recibido = datos[0].read()
        if not recibido:
            break
        datos[1] += recibido
    while b"\n" in datos[1]:
        linea, datos[1] = datos[1].split(b"\n", 1)
        try:
            datos[2] = linea.decode().strip()
            datos[3] = True
        except UnicodeError:
            pass
    if len(datos[1]) > 512:
        datos[1] = datos[1][-512:]
    return datos
def uart_hay_linea(puerto, bloque):
    datos = uart_puerto(puerto, bloque)
    nueva, datos[3] = datos[3], False
    return nueva

